MoeKernelKind = Literal["up", "down"]
Fp8WeightScaleLayout = Literal["channel", "block128", "block128_interleaved8"]
VALID_KERNEL_TYPES = ("warp", "qmma", "wgmma", "tcgen", "warpgemv")
BLOCK_SCHEDULED_FP8_KERNEL_TYPES = ("warp", "qmma", "wgmma")
MXFP4_KERNEL_TYPES = ("tcgen", "warpgemv", "warp")


def is_block_scheduled_fp8_kernel(kernel_type: str | None) -> bool:
    return kernel_type in BLOCK_SCHEDULED_FP8_KERNEL_TYPES


@dataclass(frozen=True)
class MoeVariant:
    """One CuTe MoE kernel variant: a single point in the tuning space.

    Identifies a unique cubin in the shipped bundle (or a JIT-compiled
    entry) and is the single source of truth for the variant-key format
    used by both the build helpers in `scripts/precompile/cubin_bundles`
    and the runtime dispatch in `cute_moe/dispatch.py`.
    """

    kind: str                    # "up" or "down"
    block_m: int
    block_n: int
    block_k: int
    num_warps: int
    num_stages: int
    N: int                       # Output channels (from config model dims)
    K: int                       # Input channels
    dtype: str = "bf16"          # "bf16", "fp8", or "mxfp4"
    kernel_type: str = "warp"    # "warp" | "wgmma" | "qmma" | "tcgen"
    compact_schedule: bool = False  # AOT key: compact block-offset routing.
    use_pdl: bool = False        # Enables griddepcontrol launch overlap
    cluster_M: int = 1           # tcgen-only — 2-CTA cluster mode for tcgen05.mma
    weight_scale_layout: str = "channel"  # FP8 only: channel or Qwen block scale.

    # Set of arch numbers (e.g. {89, 90, 120}) whose shipped GPU
    # configs picked this variant. Used by the AOT precompile arch
    # filter to skip building a variant for an arch class no GPU at
    # that class would ever invoke. Excluded from hash/eq so set
    # dedup still folds shape-equal variants — the manifest merges
    # the arch sets BEFORE constructing the MoeVariant.
    gpu_arches: frozenset = field(
        default_factory=frozenset,
        compare=False,
        hash=False,
    )

    def __post_init__(self) -> None:
        if self.compact_schedule and (
            self.kernel_type != "wgmma" or self.dtype != "fp8"
        ):
            raise ValueError("compact_schedule is only valid for FP8 WGMMA variants")
        if self.weight_scale_layout not in (
            "channel",
            "block128",
            "block128_interleaved8",
        ):
            raise ValueError(
                f"unsupported FP8 weight scale layout: {self.weight_scale_layout!r}"
            )
        if self.weight_scale_layout != "channel" and self.dtype != "fp8":
            raise ValueError("non-channel weight scale layouts are FP8-only")

    @property
    def mul_routed_weight(self) -> bool:
        return self.kind == "down"

    @property
    def top_k(self) -> int:
        return 1 if self.kind == "down" else 8

    @property
    def variant_key(self) -> str:
        """Schema-v2 manifest key for this variant."""
        if self.compact_schedule:
            kernel_suffix = "_wgmma_compact"
        else:
            kernel_suffix = {
                "warp": "",
                "wgmma": "_wgmma",
                "qmma": "_qmma",
                "tcgen": "_tcgen",
            }[self.kernel_type]
        pdl_suffix = "_pdl" if self.use_pdl else ""
        dtype_suffix = {
            "bf16": "",
            "fp8": "_fp8",
            "mxfp4": "_mxfp4",
        }[self.dtype]
        scale_suffix = {
            "channel": "",
            "block128": "_sblk128",
            "block128_interleaved8": "_sblk128i8",
        }[self.weight_scale_layout]
        # cluster_M only matters for tcgen (other kernels ignore it). Add a
        # `_c{N}` suffix when > 1 so tuned cluster_M=2 variants don't alias
        # against cluster_M=1 cubins in the AOT bundle. Default cluster_M=1
        # keeps the suffix empty — backwards-compatible with existing keys.
        cluster_suffix = (
            f"_c{self.cluster_M}"
            if self.kernel_type == "tcgen" and self.cluster_M > 1
            else ""
        )
        topk_suffix = (
            "_twfp32"
            if self.dtype == "bf16"
            and self.mul_routed_weight
            and self.kernel_type != "tcgen"
            else ""
        )
        return (
            f"{self.kind}_m{self.block_m}_n{self.block_n}_k{self.block_k}"
            f"_N{self.N}_K{self.K}_w{self.num_warps}_s{self.num_stages}"
            f"{dtype_suffix}{kernel_suffix}{scale_suffix}{pdl_suffix}{cluster_suffix}"
            f"{topk_suffix}"
        )


@dataclass(frozen=True)
class WarpGemvVariant:
    """One CuTe MoE warp-GEMV layer variant and AOT bundle key."""

    kind: str
    hidden_size: int
    intermediate_size: int
    top_k: int
    dtype: str = "fp8"
    warps_per_block: int = 8
    topk_weight_dtype: str = "bf16"
    weight_scale_layout: str = "channel"
    activation: str = "gelu"

    @property
    def variant_key(self) -> str:
        if self.dtype not in ("bf16", "fp8", "mxfp4"):
            raise ValueError(f"unsupported warpgemv dtype: {self.dtype!r}")
        if self.weight_scale_layout not in (
            "channel",
            "block128",
            "block128_interleaved8",
        ):
            raise ValueError(
                f"unsupported warpgemv weight layout: {self.weight_scale_layout!r}"
            )
        if self.weight_scale_layout != "channel" and self.dtype == "mxfp4":
            raise ValueError("MXFP4 warpgemv requires channel weight scale layout")
        if self.activation not in ("gelu", "geglu", "swiglu"):
            raise ValueError(f"unsupported warpgemv activation: {self.activation!r}")
        topk_suffix = (
            "_twfp32"
            if self.kind in ("down", "down_slots")
            and self.topk_weight_dtype == "fp32"
            else ""
        )
        scale_suffix = {
            "channel": "",
            "block128": "_sblk128",
            "block128_interleaved8": "_sblk128i8",
        }[self.weight_scale_layout]
        dtype_tag = {
            "bf16": "bf16_w16a16",
            "fp8": "fp8_w8a16",
            "mxfp4": "mxfp4_w4a16",
        }[self.dtype]
        activation_suffix = (
            f"_{self.activation}" if self.kind == "gate" else ""
        )
        return (
            f"{self.kind}_{dtype_tag}"
            f"_H{self.hidden_size}_I{self.intermediate_size}"
            f"_k{self.top_k}_w{self.warps_per_block}{scale_suffix}"
            f"{activation_suffix}{topk_suffix}"
        )


@dataclass(frozen=True)
class CuteMoeConfig:
    # Routed-GEMM tile fields are None for warpgemv, which only reads num_warps.
    block_m: int | None
    block_n: int | None
    block_k: int | None
    num_warps: int
    num_stages: int | None
    dtype: str  # "bf16", "fp8", or "mxfp4"
    kernel_type: str  # "warp", "qmma", "wgmma", "tcgen", or "warpgemv"
    # SM100/tcgen-only: 2-CTA cluster mode for tcgen05.mma. cluster_M=2 unlocks
    # speedup at low M for 'up' on the pre-permute path's predecessor; benched
    # neutral after the A.index_select migration so production stays at 1.
    # Ignored for non-tcgen paths.
    cluster_M: int = 1
    # Generated selector decision. Older rows omit this and remain non-PDL.
    use_pdl: bool = False

    def __post_init__(self) -> None:
        """Validate config constraints at construction time."""
        if self.dtype not in ("bf16", "fp8", "mxfp4"):
            raise ValueError(
                f"dtype must be 'bf16', 'fp8', or 'mxfp4', got '{self.dtype}'"
            )
        if self.kernel_type not in VALID_KERNEL_TYPES:
            raise ValueError(
                f"kernel_type must be one of {VALID_KERNEL_TYPES}, "
                f"got '{self.kernel_type}'"
            )
        if self.use_pdl and (self.dtype != "bf16" or self.kernel_type != "tcgen"):
            raise ValueError("use_pdl is supported only by BF16 tcgen kernels")
        if self.dtype == "mxfp4" and self.kernel_type not in MXFP4_KERNEL_TYPES:
            supported = ", ".join(MXFP4_KERNEL_TYPES)
            raise ValueError(f"MXFP4 MoE is supported only by {supported}.")
        if self.kernel_type == "warpgemv":
            if self.dtype not in ("bf16", "fp8", "mxfp4"):
                raise ValueError(
                    "warpgemv supports BF16 W16A16, FP8 W8A16, and MXFP4 W4A16 weights."
                )
            if self.num_warps <= 0:
                raise ValueError("warpgemv kernel requires num_warps > 0.")
            set_fields = [
                name
                for name in ("block_m", "block_n", "block_k", "num_stages")
                if getattr(self, name) is not None
            ]
            if set_fields:
                raise ValueError(
                    "warpgemv does not read routed-GEMM tile fields: "
                    + ", ".join(set_fields)
                )
            return

        missing = [
            name
            for name in ("block_m", "block_n", "block_k", "num_stages")
            if getattr(self, name) is None
        ]
        if missing:
            raise ValueError(
                f"{self.kernel_type} kernel requires routed-GEMM tile fields: "
                + ", ".join(missing)
            )

        # SM100 'tcgen' path uses block_m/block_n directly as the underlying
        # MoeFp8GemmSm100 mma_tiler — no per-kind warp/wgmma/qmma alignment
        # constraints apply. Skip the kernel-type-specific checks below.
        if self.kernel_type == "tcgen":
            return

        # CRITICAL: block_m must not exceed num_threads!
        # The kernel's metadata loading loop uses `if tx < block_m` to load per-row
        # metadata into shared memory. With only num_threads threads, rows beyond
        # num_threads-1 read uninitialized shared memory -> illegal memory access.
        if self.block_m > self.num_threads:
            raise ValueError(
                f"block_m ({self.block_m}) must not exceed num_threads ({self.num_threads}). "
                f"With {self.num_warps} warps, max block_m is {self.num_threads}."
            )

        if self.dtype == "fp8":
            self._validate_fp8()
        else:
            self._validate_bf16()

    def _validate_bf16(self) -> None:
        """Validate constraints for BF16 kernel based on kernel_type."""
        # block_k must be divisible by 16 (MMA K dimension for BF16).
        if self.block_k % 16 != 0:
            raise ValueError(
                f"block_k ({self.block_k}) must be divisible by 16 (BF16 MMA K dimension)."
            )

        if self.kernel_type == "wgmma":
            # WGMMA constraints
            if self.block_m % 64 != 0:
                raise ValueError(
                    f"BF16 WGMMA requires block_m ({self.block_m}) to be divisible by 64."
                )
            if self.block_k % 32 != 0:
                raise ValueError(
                    f"BF16 WGMMA requires block_k ({self.block_k}) to be divisible by 32."
                )
            # WGMMA requires (block_m // 64) warpgroups, each warpgroup = 4 warps
            required_warpgroups = self.block_m // 64
            required_warps = required_warpgroups * 4
            if self.num_warps != required_warps:
                raise ValueError(
                    f"BF16 WGMMA requires num_warps={required_warps} for block_m={self.block_m} "
                    f"(got {self.num_warps}). Each warpgroup (4 warps) handles 64 rows."
                )
        elif self.kernel_type == "warp":
            # Warp kernel constraints
            # block_m must be multiple of 16 (MMA atom M dimension)
            if self.block_m % 16 != 0:
                raise ValueError(
                    f"BF16 warp kernel requires block_m ({self.block_m}) to be divisible by 16."
                )
            # block_n must be divisible by 8 * num_warps (MMA layout constraint)
            mma_n_coverage = 8 * self.num_warps
            if self.block_n % mma_n_coverage != 0:
                raise ValueError(
                    f"block_n ({self.block_n}) must be divisible by 8 * num_warps ({mma_n_coverage})."
                )
            # block_n=32 with num_warps=8 fails LDSM alignment verification
            if self.block_n == 32 and self.num_warps == 8:
                raise ValueError(
                    "block_n=32 with num_warps=8 causes LDSM alignment verification failure."
                )
        elif self.kernel_type == "qmma":
            raise ValueError("BF16 does not support kernel_type='qmma' (FP8-only path).")

        # Shared memory constraint: sA + sB + metadata must fit in H100's 228KB.
        # BF16 = 2 bytes per element.
        bytes_per_elem = 2
        sA_bytes = self.num_stages * self.block_m * self.block_k * bytes_per_elem
        sB_bytes = self.num_stages * self.block_n * self.block_k * bytes_per_elem
        total_bytes = sA_bytes + sB_bytes
        max_bytes = 200 * 1024
        if total_bytes > max_bytes:
            raise ValueError(
                f"Shared memory exceeded: sA={sA_bytes // 1024}KB + sB={sB_bytes // 1024}KB "
                f"= {total_bytes // 1024}KB "
                f"(stages={self.num_stages}, m={self.block_m}, n={self.block_n}, k={self.block_k}). "
                f"Max ~{max_bytes // 1024}KB."
            )

    def _validate_fp8(self) -> None:
        """Validate constraints for FP8 kernels based on kernel_type."""
        if self.kernel_type == "wgmma":
            # FP8 WGMMA requires block_m to be a multiple of 64 (one warpgroup per 64 rows).
            if self.block_m % 64 != 0:
                raise ValueError(
                    f"FP8 WGMMA requires block_m ({self.block_m}) to be divisible by 64."
                )

            # FP8 WGMMA requires block_k divisible by 32 (K dimension alignment for FP8 MMA).
            if self.block_k % 32 != 0:
                raise ValueError(
                    f"FP8 WGMMA requires block_k ({self.block_k}) to be divisible by 32."
                )

            # FP8 WGMMA: num_warps must match warpgroups = block_m // 64, each warpgroup = 4 warps.
            required_warpgroups = self.block_m // 64
            required_warps = required_warpgroups * 4
            if self.num_warps != required_warps:
                raise ValueError(
                    f"FP8 WGMMA constraint: block_m={self.block_m} requires {required_warpgroups} "
                    f"warpgroup(s) = {required_warps} warps, but num_warps={self.num_warps}."
                )

            # Register pressure constraint: m=256 n=256 exceeds register limit.
            if self.block_m >= 256 and self.block_n >= 256:
                raise ValueError(
                    f"FP8 WGMMA: block_m={self.block_m} with block_n={self.block_n} "
                    f"exceeds register limit. Use smaller tiles."
                )
        else:  # "warp" or "qmma"
            # FP8 warp-level MMA kernel: block_m must be multiple of 16 (MMA atom M dimension)
            if self.block_m % 16 != 0:
                raise ValueError(
                    f"FP8 {self.kernel_type} kernel requires block_m ({self.block_m}) to be divisible by 16."
                )
            # block_n must be divisible by 8 * num_warps (MMA layout constraint)
            # MMA atom N=8, warps tile (1, num_warps, 1) in N dimension
            mma_n_coverage = 8 * self.num_warps
            if self.block_n % mma_n_coverage != 0:
                raise ValueError(
                    f"FP8 {self.kernel_type} kernel: block_n ({self.block_n}) must be divisible by "
                    f"8 * num_warps ({mma_n_coverage})."
                )
            # block_k should be divisible by 16 for warp-level MMA
            if self.block_k % 16 != 0:
                raise ValueError(
                    f"FP8 {self.kernel_type} kernel requires block_k ({self.block_k}) to be divisible by 16."
                )

            # QMMA FP8 currently keeps N and warp geometry fixed, while allowing
            # limited K/stage sweeps during tuning.
            if self.kernel_type == "qmma":
                if self.block_m // 16 not in (1, 2, 4, 8):
                    raise ValueError(
                        f"FP8 qmma kernel requires block_m / 16 in {{1, 2, 4, 8}} "
                        f"(got block_m={self.block_m})."
                    )
                if self.block_n != 128:
                    raise ValueError(
                        f"FP8 qmma kernel requires block_n=128 (got {self.block_n})."
                    )
                if self.block_k not in (64, 128):
                    raise ValueError(
                        f"FP8 qmma kernel requires block_k in {{64, 128}} (got {self.block_k})."
                    )
                if self.num_warps != 4:
                    raise ValueError(
                        f"FP8 qmma kernel requires num_warps=4 (got {self.num_warps})."
                    )
                if self.num_stages not in (2, 3, 4, 5):
                    raise ValueError(
                        f"FP8 qmma kernel requires num_stages in {{2, 3, 4, 5}} (got {self.num_stages})."
                    )

        # Shared memory constraint: sA + sB + metadata must fit in H100's 228KB.
        # FP8 = 1 byte per element (half of BF16).
        bytes_per_elem = 1
        sA_bytes = self.num_stages * self.block_m * self.block_k * bytes_per_elem
        sB_bytes = self.num_stages * self.block_n * self.block_k * bytes_per_elem
        total_bytes = sA_bytes + sB_bytes
        max_bytes = 200 * 1024
        if total_bytes > max_bytes:
            raise ValueError(
                f"Shared memory exceeded: sA={sA_bytes // 1024}KB + sB={sB_bytes // 1024}KB "
                f"= {total_bytes // 1024}KB "
                f"(stages={self.num_stages}, m={self.block_m}, n={self.block_n}, k={self.block_k}). "
                f"Max ~{max_bytes // 1024}KB."
            )

    @property
    def num_threads(self) -> int:
        return 32 * self.num_warps


# Conservative warp-MMA implementation for targets without a tuned BF16
# backend. This is a functional baseline, not a measured selector decision.
PORTABLE_BF16_WARP_CONFIG = CuteMoeConfig(
    block_m=16, block_n=32, block_k=64, num_warps=4, num_stages=2,
    dtype="bf16", kernel_type="warp",
)


# Functional block-scaled FP8 baseline; not a measured selector decision.
PORTABLE_FP8_WARP_CONFIG = CuteMoeConfig(
    block_m=16, block_n=32, block_k=64, num_warps=4, num_stages=2,
    dtype="fp8", kernel_type="warp",
)


def _should_use_wgmma_bf16(config: "CuteMoeConfig") -> bool:
    """Check if WGMMA BF16 kernel should be used for the given config."""
    return config.kernel_type == "wgmma"


