# Device keys that deliberately share another key's tuned config — same GPU die
# or a Modal/driver naming variant. Consulted BEFORE the heuristic same-arch
# fallback so known SKUs resolve to a guaranteed, auditable config rather than a
# fuzzy match. Add an entry here instead of duplicating a config file per SKU.
CUTE_MOE_GPU_CONFIG_ALIASES = {
    # A100 SKUs → canonical A100 config (all GA100; identical compute).
    "nvidia_a100_pcie_40gb": "nvidia_a100_80gb_pcie",
    "nvidia_a100_pcie_80gb": "nvidia_a100_80gb_pcie",
    "nvidia_a100_sxm4_40gb": "nvidia_a100_80gb_pcie",
    "nvidia_a100_sxm4_80gb": "nvidia_a100_80gb_pcie",
    # Modal sometimes reports A10G without the trailing G.
    "nvidia_a10": "nvidia_a10g",
    # Modal's H100 pool can expose Hopper as "NVIDIA H100 NVL".
    "nvidia_h100_nvl": "nvidia_h100_80gb_hbm3",
    # H200 / GH200 are sm_90 (GH100 die) — identical compute, share the H100 config.
    "nvidia_h200": "nvidia_h100_80gb_hbm3",
    "nvidia_gh200_480gb": "nvidia_h100_80gb_hbm3",
}

# Cache for CUDA architecture string
_cuda_arch: str | None = None
_cuda_device_name_key: str | None = None


def _get_cuda_arch() -> str:
    """Get the CUDA architecture string (e.g., 'sm90' for Hopper, 'sm100' for Blackwell)."""
    global _cuda_arch
    if _cuda_arch is None:
        major, minor = torch.cuda.get_device_capability()
        _cuda_arch = f"sm{major}{minor}"
    return _cuda_arch


def _get_cuda_device_name_key() -> str:
    """Get normalized GPU-name key used for config-file selection."""
    global _cuda_device_name_key
    if _cuda_device_name_key is None:
        _cuda_device_name_key = get_cuda_device_name_key()
    return _cuda_device_name_key


def _config_filename(
    num_experts: int,
    hidden_size: int,
    intermediate_size: int,
    dtype: str,
    gpu_name_key: str,
) -> str:
    return (
        f"cute_moe_E{num_experts}_H{hidden_size}_I{intermediate_size}"
        f"_{dtype}_{gpu_name_key}.json"
    )


def _pdl_config_filename(
    num_experts: int,
    hidden_size: int,
    intermediate_size: int,
    dtype: str,
    gpu_name_key: str,
) -> str:
    return (
        f"moe_pdl_E{num_experts}_H{hidden_size}_I{intermediate_size}"
        f"_{dtype}_{gpu_name_key}.json"
    )


_PDL_PAYLOAD_FIELDS = {"schema_version", "description", "shape", "configs"}
_PDL_SHAPE_FIELDS = {
    "num_experts",
    "top_k",
    "hidden_size",
    "intermediate_size",
    "gpu_key",
    "activation",
    "weight_scale_layout",
}


def validate_cute_moe_pdl_payload(
    payload: object,
    *,
    expected_shape: dict,
    allowed_tokens: set[str],
    source: str | Path,
    allow_partial_expected_shape: bool = False,
) -> dict[str, dict[str, bool]]:
    """Validate a generated runtime PDL selector and return its token rows."""
    if not isinstance(payload, dict) or set(payload) != _PDL_PAYLOAD_FIELDS:
        raise ValueError(f"PDL selector has invalid top-level fields: {source}")
    if type(payload["schema_version"]) is not int or payload["schema_version"] != 1:
        raise ValueError(f"PDL selector has unsupported schema_version: {source}")
    if not isinstance(payload["description"], str) or not payload["description"]:
        raise ValueError(f"PDL selector has invalid description: {source}")

    shape = payload["shape"]
    if not isinstance(shape, dict) or set(shape) != _PDL_SHAPE_FIELDS:
        raise ValueError(f"PDL selector has invalid shape fields: {source}")
    if (
        not isinstance(expected_shape, dict)
        or not expected_shape
        or not set(expected_shape) <= _PDL_SHAPE_FIELDS
        or (
            not allow_partial_expected_shape
            and set(expected_shape) != _PDL_SHAPE_FIELDS
        )
    ):
        raise ValueError(f"PDL selector base shape is invalid: {source}")
    for key in ("num_experts", "top_k", "hidden_size", "intermediate_size"):
        if type(shape[key]) is not int or shape[key] <= 0:
            raise ValueError(
                f"PDL selector shape {key} must be a positive integer: {source}"
            )
    if not isinstance(shape["gpu_key"], str) or not shape["gpu_key"]:
        raise ValueError(f"PDL selector gpu_key must be nonempty: {source}")
    if (
        not isinstance(shape["activation"], str)
        or shape["activation"] not in {"gelu", "geglu", "swiglu"}
    ):
        raise ValueError(f"PDL selector has invalid activation: {source}")
    if (
        not isinstance(shape["weight_scale_layout"], str)
        or shape["weight_scale_layout"] not in {
            "channel", "block128", "block128_interleaved8",
        }
    ):
        raise ValueError(f"PDL selector has invalid weight_scale_layout: {source}")
    if any(shape[key] != value for key, value in expected_shape.items()):
        raise ValueError(f"PDL selector shape does not match base config: {source}")

    configs = payload["configs"]
    if not isinstance(configs, dict) or not configs:
        raise ValueError(f"PDL selector has no configs: {source}")
    for token, row in configs.items():
        if (
            not isinstance(token, str)
            or not token.isdigit()
            or int(token) <= 0
            or str(int(token)) != token
        ):
            raise ValueError(f"PDL selector has invalid token key {token!r}: {source}")
        if token not in allowed_tokens:
            raise ValueError(
                f"PDL selector token {token} has no matching base config: {source}"
            )
        if not isinstance(row, dict) or set(row) != {"up", "down"}:
            raise ValueError(f"PDL selector tokens={token} must define up/down")
        if any(type(row[kind]) is not bool for kind in ("up", "down")):
            raise ValueError(f"PDL selector tokens={token} values must be booleans")
    return configs


def _closest_same_arch_config_file(
    *,
    num_experts: int,
    hidden_size: int,
    intermediate_size: int,
    dtype: str,
    gpu_name_key: str,
) -> tuple[str, Path] | None:
    cuda_arch = _get_cuda_arch()
    target_arch = sm_arch_number(cuda_arch)
    if target_arch == 0:
        return None

    prefix = f"cute_moe_E{num_experts}_H{hidden_size}_I{intermediate_size}_{dtype}_"
    candidates: dict[str, Path] = {}
    for path in _CONFIGS_DIR.glob(f"{prefix}*.json"):
        if not path.name.endswith(".json"):
            continue
        candidate_key = path.name[len(prefix):-len(".json")]
        if CUTE_MOE_GPU_TARGET_ARCH.get(candidate_key) == target_arch:
            candidates[candidate_key] = path

    if not candidates:
        return None

    target_tokens = set(gpu_name_key.split("_")) - {"nvidia"}
    max_overlap = max(
        len(target_tokens & (set(key.split("_")) - {"nvidia"}))
        for key in candidates
    )
    closest = get_close_matches(
        gpu_name_key,
        [
            key
            for key in candidates
            if len(target_tokens & (set(key.split("_")) - {"nvidia"})) == max_overlap
        ],
        n=1,
        cutoff=0,
    )[0]
    return closest, candidates[closest]


@lru_cache(maxsize=None)
def _load_cute_moe_configs(
    num_experts: int,
    hidden_size: int,
    intermediate_size: int,
    dtype: str,
    gpu_name_key: str,
) -> dict | None:
    """Load configs for given model shape/GPU. Return None if not found."""
    filename = _config_filename(
        num_experts,
        hidden_size,
        intermediate_size,
        dtype,
        gpu_name_key,
    )
    config_file = _CONFIGS_DIR / filename
    if not config_file.exists():
        alias_key = CUTE_MOE_GPU_CONFIG_ALIASES.get(gpu_name_key)
        alias_file = (
            _CONFIGS_DIR
            / _config_filename(
                num_experts, hidden_size, intermediate_size, dtype, alias_key
            )
            if alias_key is not None
            else None
        )
        if alias_file is not None and alias_file.exists():
            # Known SKU alias: guaranteed + silent, no fuzzy matching.
            config_file = alias_file
        else:
            # Unknown device: heuristic same-arch fallback (surfaced as a warning).
            fallback = _closest_same_arch_config_file(
                num_experts=num_experts,
                hidden_size=hidden_size,
                intermediate_size=intermediate_size,
                dtype=dtype,
                gpu_name_key=gpu_name_key,
            )
            if fallback is None:
                return None
            fallback_key, config_file = fallback
            cuda_arch = _get_cuda_arch()
            warnings.warn(
                "No exact CuTe MoE config for GPU "
                f"{gpu_name_key!r} on {cuda_arch}; using same-arch closest "
                f"GPU config {fallback_key!r} from {config_file}.",
                RuntimeWarning,
                stacklevel=2,
            )
    if not config_file.exists():
        return None
    with open(config_file) as f:
        return json.load(f)


@lru_cache(maxsize=None)
def _load_cute_moe_pdl_config(
    num_experts: int,
    hidden_size: int,
    intermediate_size: int,
    dtype: str,
    gpu_name_key: str,
) -> dict | None:
    """Load an exact generated PDL selector; missing selectors mean non-PDL."""
    selected_gpu_key = gpu_name_key
    config_file = _CONFIGS_DIR / _pdl_config_filename(
        num_experts, hidden_size, intermediate_size, dtype, gpu_name_key,
    )
    base_file = _CONFIGS_DIR / _config_filename(
        num_experts, hidden_size, intermediate_size, dtype, gpu_name_key,
    )
    if config_file.exists() and not base_file.exists():
        raise ValueError(f"PDL selector has no matching base config: {config_file}")
    if not base_file.exists():
        alias_key = CUTE_MOE_GPU_CONFIG_ALIASES.get(gpu_name_key)
        if alias_key is not None:
            alias_file = _CONFIGS_DIR / _pdl_config_filename(
                num_experts, hidden_size, intermediate_size, dtype, alias_key,
            )
            alias_base_file = _CONFIGS_DIR / _config_filename(
                num_experts, hidden_size, intermediate_size, dtype, alias_key,
            )
            if alias_file.exists() and alias_base_file.exists():
                config_file = alias_file
                base_file = alias_base_file
                selected_gpu_key = alias_key
    if not config_file.exists():
        return None
    if not base_file.exists():
        raise ValueError(f"PDL selector has no matching base config: {config_file}")
    with open(config_file) as f:
        payload = json.load(f)
    with open(base_file) as f:
        base_payload = json.load(f)
    if not isinstance(base_payload, dict):
        raise ValueError(f"PDL selector base config is invalid: {base_file}")
    base_configs = base_payload.get("configs")
    if not isinstance(base_configs, dict) or not base_configs:
        raise ValueError(f"PDL selector base config has no configs: {base_file}")
    expected_shape = {
        "num_experts": num_experts,
        "hidden_size": hidden_size,
        "intermediate_size": intermediate_size,
        "gpu_key": selected_gpu_key,
    }
    validate_cute_moe_pdl_payload(
        payload,
        expected_shape=expected_shape,
        allowed_tokens=set(base_configs),
        source=config_file,
        allow_partial_expected_shape=True,
    )
    return payload


def _get_cute_moe_pdl_decision(
    num_tokens: int,
    *,
    num_experts: int,
    hidden_size: int,
    intermediate_size: int,
    dtype: str,
) -> dict[MoeKernelKind, bool]:
    selectors = _load_cute_moe_pdl_config(
        num_experts,
        hidden_size,
        intermediate_size,
        dtype,
        _get_cuda_device_name_key(),
    )
    if selectors is None:
        return {"up": False, "down": False}
    row = selectors["configs"].get(str(num_tokens))
    if row is None:
        return {"up": False, "down": False}
    return {"up": row["up"], "down": row["down"]}


@lru_cache(maxsize=None)
def has_cute_moe_config(
    *,
    num_experts: int,
    hidden_size: int,
    intermediate_size: int,
    dtype: str = "bf16",
    num_tokens: int | None = None,
) -> bool:
    """Return whether tuned CuTe MoE configs exist for this GPU and model shape."""
    gpu_name_key = _get_cuda_device_name_key()
    configs = _load_cute_moe_configs(
        num_experts,
        hidden_size,
        intermediate_size,
        dtype,
        gpu_name_key,
    )
    if configs is None:
        return False
    token_configs = configs.get("configs", {})
    if num_tokens is None:
        return bool(token_configs)
    if any(cfg.get("exact_tokens", False) for cfg in token_configs.values()):
        config = token_configs.get(str(num_tokens))
        return bool(config is not None and config.get("exact_tokens", False))
    return bool(token_configs)


def has_exact_cute_moe_config(
    *,
    num_experts: int,
    hidden_size: int,
    intermediate_size: int,
    num_tokens: int | None = None,
    dtype: str = "bf16",
) -> bool:
    """Return whether exact authority exists, or a device-exact row is usable."""
    gpu_name_key = _get_cuda_device_name_key()
    configs = _load_cute_moe_configs(
        num_experts,
        hidden_size,
        intermediate_size,
        dtype,
        gpu_name_key,
    )
    if configs is None:
        return False
    token_configs = configs.get("configs", {})
    if num_tokens is None:
        return any(config.get("exact_tokens", False) for config in token_configs.values())
    exact_config_file = _CONFIGS_DIR / _config_filename(
        num_experts,
        hidden_size,
        intermediate_size,
        dtype,
        gpu_name_key,
    )
    if not exact_config_file.exists():
        return False
    config = token_configs.get(str(int(num_tokens)))
    return bool(config is not None and config.get("exact_tokens", False))


def resolve_cute_moe_exact_capacity(
    requested_tokens: int,
    *,
    num_experts: int,
    hidden_size: int,
    intermediate_size: int,
    dtype: str = "bf16",
) -> int | None:
    """Resolve a request to the smallest covering calibrated capacity.

    Returns ``None`` when the selected GPU/model config has no exact-capacity
    rows. If exact-capacity rows exist, requests above the generated coverage
    fail closed instead of falling through to an unrelated backend.
    """
    requested_tokens = int(requested_tokens)
    if requested_tokens <= 0:
        raise ValueError("requested_tokens must be positive")
    configs = _load_cute_moe_configs(
        num_experts,
        hidden_size,
        intermediate_size,
        dtype,
        _get_cuda_device_name_key(),
    )
    if configs is None:
        return None
    token_configs = configs.get("configs", {})
    exact_capacities = sorted(
        int(tokens)
        for tokens, config in token_configs.items()
        if config.get("exact_tokens", False)
    )
    if not exact_capacities:
        return None
    for capacity in exact_capacities:
        if capacity >= requested_tokens:
            return capacity
    raise ValueError(
        "No exact CuTe MoE capacity covers requested_tokens="
        f"{requested_tokens}; generated capacities={exact_capacities}"
    )


def resolve_cute_moe_prefill_capacity(
    requested_tokens: int,
    *,
    num_experts: int,
    hidden_size: int,
    intermediate_size: int,
    dtype: str = "bf16",
) -> int | None:
    """Resolve the physical capacity of each launch in a chunked prefill."""
    requested_tokens = int(requested_tokens)
    if requested_tokens <= 0:
        raise ValueError("requested_tokens must be positive")
    configs = _load_cute_moe_configs(
        num_experts,
        hidden_size,
        intermediate_size,
        dtype,
        _get_cuda_device_name_key(),
    )
    if configs is None:
        return None
    exact_capacities = sorted(
        int(tokens)
        for tokens, config in configs.get("configs", {}).items()
        if config.get("exact_tokens", False)
    )
    if not exact_capacities:
        return None
    return next(
        (capacity for capacity in exact_capacities if capacity >= requested_tokens),
        exact_capacities[-1],
    )


def _get_token_configs(
    *,
    num_experts: int,
    hidden_size: int,
    intermediate_size: int,
    dtype: str,
) -> dict[str, dict]:
    gpu_name_key = _get_cuda_device_name_key()
    cuda_arch = _get_cuda_arch()
    configs = _load_cute_moe_configs(
        num_experts,
        hidden_size,
        intermediate_size,
        dtype,
        gpu_name_key,
    )
    filename = _config_filename(
        num_experts,
        hidden_size,
        intermediate_size,
        dtype,
        gpu_name_key,
    )
    config_path = _CONFIGS_DIR / filename
    if configs is None:
        raise ValueError(
            "No tuned CuTe MoE config for this GPU/model/dtype "
            f"(gpu={gpu_name_key}, arch={cuda_arch}, expected={config_path})."
        )
    token_configs = configs.get("configs", {})
    if not token_configs:
        raise ValueError(
            "CuTe MoE config file is missing required section "
            f"'configs' (gpu={gpu_name_key}, file={config_path})."
        )
    return token_configs


def _select_token_config_key(configs: dict[str, dict], num_tokens: int) -> str:
    if any(cfg.get("exact_tokens", False) for cfg in configs.values()):
        key = str(num_tokens)
        config = configs.get(key)
        if config is None or not config.get("exact_tokens", False):
            raise ValueError(
                f"No exact CuTe MoE calibration for num_tokens={num_tokens}"
            )
        return key
    token_keys = [int(k) for k in configs.keys()]
    nearest = min(token_keys, key=lambda t: abs(t - num_tokens))
    return str(nearest)


def _select_token_config(configs: dict[str, dict], num_tokens: int) -> dict:
    return configs[_select_token_config_key(configs, num_tokens)]


def _select_routed_token_config(configs: dict[str, dict], num_tokens: int) -> dict:
    routed_configs = {
        key: cfg for key, cfg in configs.items()
        if "block_m" in cfg
    }
    if not routed_configs:
        raise ValueError("No routed-GEMM CuTe MoE token config is available")
    return _select_token_config(routed_configs, num_tokens)


def _select_routed_token_config_key(
    configs: dict[str, dict], num_tokens: int,
) -> str:
    routed_configs = {
        key: cfg for key, cfg in configs.items()
        if "block_m" in cfg
    }
    if not routed_configs:
        raise ValueError("No routed-GEMM CuTe MoE token config is available")
    return _select_token_config_key(routed_configs, num_tokens)


@lru_cache(maxsize=None)
def get_cute_moe_block_m(
    num_tokens: int,
    *,
    num_experts: int,
    hidden_size: int,
    intermediate_size: int,
    dtype: str = "bf16",
) -> int:
    """Get the block_m value for routing alignment.

    Routed-GEMM UP and DOWN kernels share the same block_m for a given
    token count. Non-routed buckets such as warpgemv are skipped.
    """
    token_configs = _get_token_configs(
        num_experts=num_experts,
        hidden_size=hidden_size,
        intermediate_size=intermediate_size,
        dtype=dtype,
    )

    cfg = _select_routed_token_config(token_configs, num_tokens)
    return int(cfg["block_m"])


def _make_cute_moe_config(
    kind: MoeKernelKind,
    moe_cfg: dict,
    dtype: str,
    *,
    use_pdl: bool = False,
) -> CuteMoeConfig:
    cfg = moe_cfg.get(kind)
    if cfg is None:
        raise ValueError(f"CuTe MoE token config is missing {kind!r} section")

    if cfg["kernel_type"] == "warpgemv":
        return CuteMoeConfig(
            block_m=None,
            block_n=None,
            block_k=None,
            num_warps=cfg["num_warps"],
            num_stages=None,
            dtype=dtype,
            kernel_type=cfg["kernel_type"],
            use_pdl=use_pdl,
        )

    return CuteMoeConfig(
        block_m=moe_cfg["block_m"],
        block_n=cfg["block_n"],
        block_k=cfg["block_k"],
        num_warps=cfg["num_warps"],
        num_stages=cfg["num_stages"],
        dtype=dtype,
        kernel_type=cfg["kernel_type"],
        cluster_M=cfg.get("cluster_M", 1),
        use_pdl=use_pdl,
    )


@lru_cache(maxsize=None)
def get_cute_moe_config(
    num_tokens: int,
    *,
    num_experts: int,
    hidden_size: int,
    intermediate_size: int,
    dtype: str = "bf16",
) -> dict[MoeKernelKind, CuteMoeConfig]:
    """Get the selected MoE token-bucket config. Raises if not available.

    Args:
        num_tokens: Number of tokens (batch size)
        num_experts: Number of experts (E)
        hidden_size: Hidden/model dimension (H)
        intermediate_size: Expert intermediate dimension (I)
        dtype: Data type ("bf16" or "fp8")

    Returns:
        Dict with "up" and "down" CuteMoeConfig entries for the selected token bucket.

    Raises:
        ValueError: If no GPU-specific tuned config exists for this model/dtype.
    """
    token_configs = _get_token_configs(
        num_experts=num_experts,
        hidden_size=hidden_size,
        intermediate_size=intermediate_size,
        dtype=dtype,
    )

    token_key = _select_token_config_key(token_configs, num_tokens)
    moe_cfg = token_configs[token_key]
    pdl = _get_cute_moe_pdl_decision(
        int(token_key),
        num_experts=num_experts,
        hidden_size=hidden_size,
        intermediate_size=intermediate_size,
        dtype=dtype,
    )
    return {
        "up": _make_cute_moe_config("up", moe_cfg, dtype, use_pdl=pdl["up"]),
        "down": _make_cute_moe_config("down", moe_cfg, dtype, use_pdl=pdl["down"]),
    }


@lru_cache(maxsize=None)
def get_cute_moe_routed_config(
    num_tokens: int,
    *,
    num_experts: int,
    hidden_size: int,
    intermediate_size: int,
    dtype: str = "bf16",
) -> dict[MoeKernelKind, CuteMoeConfig]:
    """Get the nearest routed-GEMM token-bucket config."""
    token_configs = _get_token_configs(
        num_experts=num_experts,
        hidden_size=hidden_size,
        intermediate_size=intermediate_size,
        dtype=dtype,
    )

    token_key = _select_routed_token_config_key(token_configs, num_tokens)
    moe_cfg = token_configs[token_key]
    pdl = _get_cute_moe_pdl_decision(
        int(token_key),
        num_experts=num_experts,
        hidden_size=hidden_size,
        intermediate_size=intermediate_size,
        dtype=dtype,
    )
    return {
        "up": _make_cute_moe_config("up", moe_cfg, dtype, use_pdl=pdl["up"]),
        "down": _make_cute_moe_config("down", moe_cfg, dtype, use_pdl=pdl["down"]),
    }
